#include "mutation3.h"
#include <stdio.h>
#include <string.h>
#include <limits.h>
/* Generation is integer-only, owns no heap, and is intended for a worker. */
static int ab(int x){return x<0?-x:x;}
static int clamp(int x,int lo,int hi){return x<lo?lo:x>hi?hi:x;}
static int sync_note(int s,int d){int u;for(u=960;u>=240;u/=2)if(s%u==0&&(s/u)%2==1&&d>u)return 1;return 0;}
static int pc(int x){x%=12;return x<0?x+12:x;}
static const int modes[5][7]={{0,2,3,5,7,8,10},{0,2,3,5,7,9,10},{0,1,3,5,7,8,10},{0,2,3,5,7,8,11},{0,2,4,5,7,9,11}};
static int degree(const m3_phrase *b,int p){int v=p-b->key,o=v/12,r=v%12,i,best=0,d=99;if(r<0){r+=12;--o;}for(i=0;i<7;i++){int z=ab(modes[b->mode][i]-r);if(z<d){d=z;best=i;}}return 7*o+best;}
static uint32_t rng(uint32_t *s){uint32_t x=*s;if(!x)x=0x9e3779b9u;x^=x<<13;x^=x>>17;x^=x<<5;*s=x;return x;}
uint32_t m3_pad_seed(uint32_t s,uint32_t n){s^=n+0x9e3779b9u+(s<<6)+(s>>2);s^=s>>16;s*=0x7feb352du;s^=s>>15;s*=0x846ca68bu;return s^(s>>16);}
uint32_t m3_context_size(void){return (uint32_t)sizeof(m3_context);}
static int small(const m3_phrase *b,int kind){return (kind*4+clamp(b->speed,0,3))*3+clamp(b->movement,0,2);}
static int row(const m3_phrase *b,int kind,int previous,int interval,int value){return (((small(b,kind)*13+previous)*31+interval)*12+value);}
static uint32_t mix(uint32_t a,uint32_t b,int dark){return (uint32_t)(((uint64_t)a*(1000-dark)+(uint64_t)b*dark+500)/1000);}
static uint32_t lut(const uint16_t *t,const m3_phrase *b,int prev,int iv,int value,int dark){return mix(t[row(b,0,prev,iv,value)],t[row(b,1,prev,iv,value)],dark);}
static uint32_t prior(const uint16_t *t,const m3_phrase *b,int stride,int value,int dark){return mix(t[small(b,0)*stride+value],t[small(b,1)*stride+value],dark);}
static int sample(uint32_t *s,const uint32_t *w,int n){uint64_t total=0,r,threshold;int i;for(i=0;i<n;i++)total+=w[i];if(!total)return (int)(rng(s)%(uint32_t)n);threshold=(0-total)%total;do{r=(uint64_t)rng(s)<<32;r|=rng(s);}while(r<threshold);r%=total;for(i=0;i<n;i++){if(r<w[i])return i;r-=w[i];}return n-1;}
int m3_load(m3_context *c,const char *path){FILE *f;char magic[8];uint32_t size;size_t bytes;if(!c||!path)return -1;f=fopen(path,"rb");if(!f)return -2;if(fread(magic,1,8,f)!=8||memcmp(magic,"TTMM3V01",8)||fread(&size,4,1,f)!=1||size!=(uint32_t)(offsetof(m3_context,back))){fclose(f);return -3;}bytes=fread(c,1,size,f);if(bytes!=size||fgetc(f)!=EOF||c->pattern_count<0||c->pattern_count>M3_PATTERNS){fclose(f);return -4;}fclose(f);return 0;}
/* Backward messages on 12 pitch classes: a soft first-order marginal bridge.
   This is NOT hard arc consistency and does not guarantee musical satisfaction. */
static void propagate(m3_context *c,const m3_phrase *b,int dark){int i,p,q;for(i=0;i<b->count;i++){const m3_note *n=&b->notes[i];int strong=n->start%1920==0,tones=0;uint32_t h=prior(c->hit,b,2,strong,dark);for(p=0;p<12;p++)tones+=(n->chord>>p)&1u;for(p=0;p<12;p++){uint32_t v=65535/12;if(n->chord){v=(n->chord&(1u<<p))?h/(uint32_t)tones:(65535u-h)/(uint32_t)(12-tones);}if(n->bass>=0)v=(uint32_t)(((uint64_t)(v+1)*prior(c->bass,b,13,pc(p-n->bass),dark))>>16);c->emission[i][p]=v+1;}}
 for(p=0;p<12;p++)c->back[b->count-1][p]=65535;
 for(i=b->count-2;i>=0;i--){uint64_t vals[12],max=1;int root=b->notes[i+1].root>=0?b->notes[i+1].root:b->key;for(p=0;p<12;p++){uint64_t sum=0;for(q=0;q<12;q++){uint32_t t=lut(c->trans,b,pc(p-root),30,pc(q-root),dark);sum+=((uint64_t)t*c->emission[i+1][q]*c->back[i+1][q])>>24;}vals[p]=sum;if(sum>max)max=sum;}for(p=0;p<12;p++)c->back[i][p]=(uint32_t)(vals[p]*65534/max)+1;}}
static int proposed(m3_context *c,const m3_phrase *b,const m3_phrase *w,int i,int dark,int reverse,uint32_t *seed,const unsigned char *allowed){uint64_t values[128],maximum=1;int shift=0;int p,root=b->notes[i].root>=0?b->notes[i].root:b->key,prev=12,iv=30,center=0,j;for(j=0;j<b->count;j++)center+=b->notes[j].pitch;center/=b->count;if(i>0){prev=pc(w->notes[i-1].pitch-root);if(i>1)iv=clamp(degree(b,w->notes[i-1].pitch)-degree(b,w->notes[i-2].pitch),-14,14)+14;}
 for(p=0;p<128;p++){uint64_t v=(uint64_t)(lut(c->trans,b,prev,iv,pc(p-root),dark)+1)<<24;v=v*(prior(c->reg,b,255,p-center+127,dark)+1)>>16;v=v*(c->emission[i][pc(p)]+1)>>14;v=v*(c->back[i][pc(p)]+1)>>16;if(i>0)v=v*(prior(c->jump,b,255,p-w->notes[i-1].pitch+127,dark)+1)>>16;
 if(reverse&&i+1<b->count){int nextiv=i+2<b->count?clamp(degree(b,w->notes[i+2].pitch)-degree(b,w->notes[i+1].pitch),-14,14)+14:30;uint32_t r=lut(c->reverse,b,pc(w->notes[i+1].pitch-root),nextiv,pc(p-root),dark);uint32_t jumpnext=prior(c->jump,b,255,w->notes[i+1].pitch-p+127,dark);v=v*(r+1)>>16;v=v*(jumpnext+1)>>16;}
 values[p]=v;if(v>maximum)maximum=v;}while(maximum>UINT32_MAX-1u){maximum>>=1;++shift;}for(p=0;p<128;p++)c->weights[p]=(!allowed||allowed[p])?(uint32_t)(values[p]>>shift)+1:0;
 return sample(seed,c->weights,128);}
static int32_t avg(int64_t v,int n){return n?(int32_t)(v/n):0;}
/* Twelve comparable integer diagnostics; learned location/dispersion penalize
   departures in either direction. No feature is independently maximized. */
void m3_features(m3_context *c,const m3_phrase *b,const m3_phrase *w,int32_t *f){int i,lo=127,hi=0,covered=0,hit=0,proper=0,strong=0,stronghit=0,cons_lut[12]={1000,100,416,603,725,803,576,916,632,776,566,380};int64_t tension=0,prox=0,inv=0,cons=0,pcs=0,dist=0,reg=0,distden=0;int pcden=0;int center=0;memset(f,0,12*sizeof(*f));for(i=0;i<b->count;i++)center+=b->notes[i].pitch;center/=b->count;
 for(i=0;i<w->count;i++){int p=w->notes[i].pitch;uint32_t mask=w->notes[i].chord;int j;if(p<lo)lo=p;if(p>hi)hi=p;reg+=p-center;tension+=c->tension[(b->mode*12+b->key)*12+pc(p)];if(mask){int yes=(mask&(1u<<pc(p)))!=0;covered++;hit+=yes;if(!yes&&i+1<w->count&&ab(w->notes[i+1].pitch-p)<=2)proper++;if(w->notes[i].start%1920==0){strong++;stronghit+=yes;}}
 for(j=0;j<w->chord_count;j++){const m3_chord *ch=&w->chords[j];int a=w->notes[i].start>ch->start?w->notes[i].start:ch->start,finish=w->notes[i].start+w->notes[i].duration,z=finish<ch->end?finish:ch->end;if(z>a&&ch->mask){int v,sv=0,votes=0,grid=(z+239)/240-(a+239)/240;dist+=(int64_t)(z-a)*c->distance[ch->mask*12+pc(p)];distden+=z-a;for(v=0;v<ch->count;v++)if(ch->pitches[v]<=p){int rel=pc(p-ch->pitches[v]);sv+=(rel==0||rel==3||rel==4||rel==7||rel==8||rel==9)?1000:rel==5?0:-1000;votes++;}if(votes&&grid){pcs+=(int64_t)grid*sv/votes;pcden+=grid;}}}
 if(i){int d=p-w->notes[i-1].pitch;prox+=ab(d)*1000;cons+=cons_lut[ab(d)%12];if(i>1&&w->notes[i].start-(w->notes[i-1].start+w->notes[i-1].duration)<=960){int a=w->notes[i-1].pitch-w->notes[i-2].pitch,rev=a*d<0;inv+=(ab(a)>6&&d)?(rev?1000:-1000):0;inv+=(rev&&ab(a+d)<=2)?1500:0;}}}
 f[0]=avg(tension,w->count);f[1]=avg(prox,w->count-1);f[2]=avg(inv,w->count-2);f[3]=avg(cons,w->count-1);f[4]=covered?(hit+proper)*1000/covered:0;f[5]=avg(pcs,pcden);f[6]=distden?(int32_t)(dist/distden):0;f[7]=(hi-lo)*1000;f[8]=strong?stronghit*1000/strong:0;f[9]=avg(reg*1000,w->count);/* rhythm diagnostics */
 for(i=0;i<w->count;i++){int s=w->notes[i].start,d=w->notes[i].duration,q=s%960;if(q)f[10]+=1000;if(sync_note(s,d))f[11]+=1000;}f[10]/=w->count;f[11]/=w->count;}
int m3_score(m3_context *c,const m3_phrase *b,const m3_phrase *w,int dark){int32_t f[12];int i;int64_t cost=0;m3_features(c,b,w,f);for(i=0;i<12;i++){int32_t a=c->targets[small(b,0)*12+i],z=c->targets[small(b,1)*12+i],sa=c->scales[small(b,0)*12+i],sz=c->scales[small(b,1)*12+i];int64_t t=((int64_t)a*(1000-dark)+(int64_t)z*dark)/1000,s=((int64_t)sa*(1000-dark)+(int64_t)sz*dark)/1000,penalty=(int64_t)ab(f[i]-(int)t)*1000/(s>0?s:1);if(i>=1&&i<=3){int den=ab(c->expectation[1])+ab(c->expectation[2])+ab(c->expectation[3]);if(!c->expectation[0])continue;penalty=penalty*3*ab(c->expectation[i])/(den?den:1);}cost+=penalty;}return cost>INT_MAX?INT_MAX:(int)cost;}
static int rhythm(m3_context *c,const m3_phrase *b,const m3_params *p,m3_phrase *out,uint32_t *seed){int j,i,bestdiff=INT_MAX,eligible=0,selected=-1;int64_t best=INT64_MAX;for(j=0;j<c->pattern_count;j++){m3_pattern *r=&c->patterns[j];int diff;if(r->speed!=b->speed||r->length!=b->length||r->groove!=b->groove)continue;diff=ab(r->count-b->count);if(diff<bestdiff){bestdiff=diff;eligible=0;}if(diff==bestdiff)eligible++;}if(!eligible)return M3_NO_COMPATIBLE_RHYTHM;
 /* Bounded candidate sampling, uniform over all compatible nearest-N patterns. */
 for(i=0;i<p->candidates;i++){int pick=(int)(rng(seed)%(uint32_t)eligible),rank=0;for(j=0;j<c->pattern_count;j++){m3_pattern *r=&c->patterns[j];if(r->speed==b->speed&&r->length==b->length&&r->groove==b->groove&&ab(r->count-b->count)==bestdiff){if(rank++==pick){selected=j;break;}}}if(selected>=0){m3_pattern *r=&c->patterns[selected];int64_t displacement=0,score;int off=0,sync=0;
 c->work=*b;for(j=0;j<b->count;j++){int src=j*r->count/b->count;int s=r->starts[src],d=r->durations[src];if(b->count>r->count){int first=(src*b->count+r->count-1)/r->count,last=((src+1)*b->count+r->count-1)/r->count,copies=last-first;int step=d/copies;if(step<1)step=1;s+=(j-first)*step;d=step;}if(j&&s<c->work.notes[j-1].start)s=c->work.notes[j-1].start;if(s>=b->length)s=b->length-1;if(d>b->length-s)d=b->length-s;if(d<1)d=1;c->work.notes[j].start=s;c->work.notes[j].duration=d;displacement+=ab(s-b->notes[j].start)+ab(d-b->notes[j].duration);off+=s%960!=0;sync+=sync_note(s,d);}
 /* Match measured rhythm distributions rather than maximize syncopation. */
 score=displacement*(1000-p->intensity)/(b->count?b->count:1);
 {int idx=(clamp(b->speed,0,3)*3+clamp(b->movement,0,2))*4;int so=c->rhythm_targets[idx+1],ss=c->rhythm_targets[idx+3];score+=(int64_t)ab(off*1000/b->count-c->rhythm_targets[idx])*1000000*p->intensity/(so>0?so:1);score+=(int64_t)ab(sync*1000/b->count-c->rhythm_targets[idx+2])*1000000*p->intensity/(ss>0?ss:1);}
 if(score<best){best=score;*out=c->work;}}}
 return bestdiff?M3_NEAREST_N:0;}
int m3_generate_supported(m3_context *c,const m3_phrase *b,const m3_params *p,m3_phrase *out,const unsigned char allowed[M3_NOTES][128]){uint32_t seed;int i,k,pass,warn=0,best=INT_MAX;if(!c||!b||!p||!out||b->count<1||b->count>128||b->length<1||b->chord_count<0||b->chord_count>512||b->mode<0||b->mode>4||b->key<0||b->key>11||p->intensity<0||p->intensity>1000||p->dark<0||p->dark>1000||p->candidates<8||p->candidates>32||p->passes<1||p->passes>8||p->operation<0||p->operation>2)return -1;*out=*b;if(!p->intensity)return 0;for(i=0;i<b->count;i++)if(b->notes[i].pitch<0||b->notes[i].pitch>127||b->notes[i].start<0||b->notes[i].duration<1||(int64_t)b->notes[i].start+b->notes[i].duration>b->length||b->notes[i].chord>4095||b->notes[i].root< -1||b->notes[i].root>11||b->notes[i].bass< -1||b->notes[i].bass>127||b->notes[i].velocity<0||b->notes[i].velocity>127)return -2;seed=p->seed;if(p->operation==1)return rhythm(c,b,p,out,&seed);if(allowed){for(i=0;i<b->count;i++){int j,any=0;for(j=0;j<128;j++)any|=allowed[i][j];if(!any)return -3;}}for(i=0;i<b->count;i++){c->mask[i]=(int)(rng(&seed)%1000)<p->intensity;if(!b->notes[i].chord||b->notes[i].bass<0)warn|=M3_MISSING_HARMONY;}propagate(c,b,p->dark);
 for(k=0;k<p->candidates;k++){int score;c->work=*b;for(i=0;i<b->count;i++)if(c->mask[i])c->work.notes[i].pitch=proposed(c,b,&c->work,i,p->dark,0,&seed,allowed?allowed[i]:NULL);if(p->operation==2)for(pass=0;pass<p->passes;pass++){for(i=0;i<b->count;i++)if(c->mask[i]&&rng(&seed)%(uint32_t)p->passes<(uint32_t)(p->passes-pass))c->work.notes[i].pitch=proposed(c,b,&c->work,i,p->dark,1,&seed,allowed?allowed[i]:NULL);}score=m3_score(c,b,&c->work,p->dark);if(score<best){best=score;*out=c->work;}}
 return warn;}

/* NULL preserves the original draw sequence and all legacy results. */
int m3_generate(m3_context *c,const m3_phrase *b,const m3_params *p,m3_phrase *out){return m3_generate_supported(c,b,p,out,NULL);}
